# Viva — slot D3 (part A): vascular disorders & ulcers (6 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — vascular chapter (venous drainage of
# lower limb, chronic leg ulcers, evaluation and classification of vasculitis, classify purpura, painful bruising,
# Milroy disease, glomus tumour), vascular anomalies (Klippel–Trenaunay, blue rubber bleb, syndromes with vascular
# anomalies), lasers for vascular lesions; facts checked with IADVL 5e, ISSVA 2018 classification and EULAR/PRINTO/PRES criteria.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Leg ulcers", src=f"{PYQ}; {IA} (Leg ulcers, venous disease)",
 qa=[
 ("Define a chronic leg ulcer.", ["Loss of skin below the knee (leg or foot) that does not heal within 4–6 weeks"]),
 ("Classify leg ulcers by cause (PYQ).", ["Vascular: venous (70–80%), arterial (10–15%), mixed arteriovenous, lymphatic, vasculitic (PAN, rheumatoid, cryoglobulinaemia, ANCA), microthrombotic (antiphospholipid, livedoid vasculopathy, calciphylaxis, cholesterol emboli)", "Neuropathic (trophic): diabetes, leprosy, spinal disorders, alcohol, tabes dorsalis", "Infective: tropical ulcer, ecthyma, mycobacterial (TB, Buruli, leprosy), deep fungal (mycetoma, sporotrichosis), leishmaniasis, syphilis (gumma), yaws", "Haematological: sickle-cell disease, thalassaemia, hereditary spherocytosis, polycythaemia, dysproteinaemias", "Neoplastic: SCC (Marjolin's ulcer in chronic scars), BCC, melanoma, lymphoma, Kaposi sarcoma", "Others: pyoderma gangrenosum, necrobiosis lipoidica, trauma, burns, dermatitis artefacta, drugs (hydroxyurea — malleolar ulcers), radiation, panniculitis"]),
 ("Describe the venous drainage of the lower limb (PYQ).", ["Superficial veins: great saphenous (from medial end of dorsal arch, anterior to medial malleolus, along medial leg and thigh to saphenofemoral junction 3–4 cm below and lateral to pubic tubercle) and small saphenous (behind lateral malleolus, up the back of calf to popliteal vein)", "Deep veins: paired venae comitantes of anterior/posterior tibial and peroneal veins → popliteal → femoral → external iliac", "Perforators connect superficial to deep with valves directing flow inwards (Cockett's medial ankle perforators, Boyd's below knee, Dodd's/Hunter's in thigh)", "Calf muscle pump: contraction compresses deep veins and pushes blood upwards; valves prevent reflux — failure gives ambulatory venous hypertension"]),
 ("Explain the pathogenesis of venous ulcers.", ["Valvular incompetence (primary, or post-thrombotic) and calf pump failure → sustained ambulatory venous hypertension → capillary distension and leakage of fibrinogen, RBCs → pericapillary fibrin cuffs (oxygen diffusion barrier hypothesis), leucocyte trapping (white cell trapping hypothesis), growth-factor trapping, MMP activity → tissue hypoxia, inflammation and ulceration"]),
 ("Describe the clinical features of a venous ulcer and its associated signs.", ["Site: gaiter area — above the medial malleolus (commonest), shallow, irregular sloping edges, granulation tissue and fibrinous slough, moderate exudate; mild pain relieved by elevation", "Surrounding changes: varicose veins, oedema, haemosiderin pigmentation (brown), stasis (venous) eczema, lipodermatosclerosis (inverted champagne-bottle leg), atrophie blanche (white stellate scars with telangiectasia), corona phlebectatica (ankle flare)", "CEAP classification: C0 none — C1 telangiectasia/reticular — C2 varicose veins — C3 oedema — C4 skin changes (a pigmentation/eczema, b LDS/atrophie blanche, c corona phlebectatica) — C5 healed ulcer — C6 active ulcer"]),
 ("Differentiate venous, arterial and neuropathic ulcers.", ["Venous: gaiter area, shallow, irregular, exudative, mild pain eased by elevation, pulses present, warm, oedema, pigmentation", "Arterial: distal pressure points (toes, heel, shin, lateral malleolus), punched-out, deep, dry pale/necrotic base, severe pain worse on elevation and at night, absent pulses, cold shiny hairless skin, intermittent claudication, ABPI <0.8", "Neuropathic: pressure points of sole (metatarsal heads, heel), punched-out painless with callus rim, sensory loss, warm foot with pulses (unless mixed diabetic), deformity (Charcot joint)"]),
 ("Discuss the evaluation of a leg ulcer.", ["History: duration, pain, DVT, varicose veins, diabetes, smoking, trauma, drugs, systemic disease", "Examination: site, size (measure/photograph), edge, base, discharge, surrounding skin, pulses, sensation, joints", "Ankle–brachial pressure index (ABPI) with hand-held Doppler: 0.9–1.3 normal; <0.8 arterial disease (avoid high compression); <0.5 severe ischaemia; >1.3 calcified vessels (diabetes — use toe pressures)", "Venous duplex ultrasound (reflux, obstruction); arterial duplex/angiography if ABPI low", "Bloods: CBC, sugar/HbA1c, renal function, albumin, ESR/CRP, lipid profile, autoimmune screen (ANA, ANCA, RF, cryoglobulins, APLA) when vasculitic", "Swab culture only if clinically infected; biopsy from edge if atypical, non-healing >3 months (SCC), PG/vasculitis suspected; X-ray/MRI for osteomyelitis"]),
 ("Management of venous ulcers.", ["Compression therapy — cornerstone: multilayer bandage systems (4-layer, 2-layer short-stretch) delivering ~40 mmHg at ankle if ABPI ≥0.8; reduced compression if ABPI 0.5–0.8; then compression stockings class II–III lifelong to prevent recurrence", "Leg elevation, walking/calf exercises, weight loss", "Wound bed preparation (TIME — Tissue debridement, Infection/inflammation control, Moisture balance, Edge advancement): sharp/autolytic/enzymatic/larval debridement; appropriate dressings (hydrocolloid, foam, alginate for exudate, hydrogel for dry, silver/iodine for infection)", "Pentoxifylline 400 mg TDS (improves healing), micronised purified flavonoid fraction (MPFF), aspirin (limited evidence)", "Treat stasis eczema with topical steroid (avoid sensitisers — check patch test), treat infection with systemic antibiotics", "Surgery: endovenous ablation of superficial reflux (EVLA, radiofrequency, foam sclerotherapy) — reduces recurrence (EVRA trial); split-thickness skin grafting, pinch grafts, cellular/tissue-based skin substitutes, PRP, NPWT for large ulcers"]),
 ("What is Marjolin's ulcer?", ["Aggressive SCC arising in a chronic ulcer or scar (burns, venous ulcers, osteomyelitis sinus, DLE, lupus vulgaris); suspect with raised everted edge, bleeding, rapid growth, failure to heal — biopsy"]),
 ("What is the TIME concept?", ["Framework for wound bed preparation: T — non-viable Tissue removal; I — Infection/Inflammation control; M — Moisture balance; E — Edge of wound (non-advancing/undermined) — later extended to TIMERS (Regeneration, Social factors)"]),
 ("Write short notes on Milroy disease (PYQ).", ["Primary congenital lymphoedema (type I) — autosomal dominant FLT4 (VEGFR-3) mutation; bilateral lower-limb lymphoedema at or soon after birth, upslanting toenails, prominent veins, papillomatosis, hydrocele; lymphoscintigraphy shows absent uptake; treated with compression, skin care, prevention of cellulitis", "Other primary lymphoedema: Meige disease (lymphoedema praecox, puberty), lymphoedema tarda (>35 y), lymphoedema–distichiasis (FOXC2)"]),
 ],
 spot=["Gaiter-area shallow ulcer + pigmentation + LDS — venous ulcer", "ABPI <0.8 — no high compression", "Non-healing ulcer with rolled edge — biopsy for Marjolin's SCC"]),

dict(case="Infantile haemangioma & vascular malformations", src=f"{PYQ}; {IA} (Vascular anomalies); ISSVA 2018 classification",
 qa=[
 ("Give the ISSVA classification of vascular anomalies.", ["Vascular tumours (endothelial proliferation): benign — infantile haemangioma, congenital haemangioma (RICH, NICH, PICH), tufted angioma, spindle-cell haemangioma, pyogenic granuloma; locally aggressive/borderline — kaposiform haemangioendothelioma, Kaposi sarcoma; malignant — angiosarcoma", "Vascular malformations (errors of morphogenesis, no proliferation): simple — capillary (CM, port-wine stain), venous (VM), lymphatic (LM — macro/microcystic), arteriovenous (AVM, high flow), AV fistula; combined (CVM, CLVM, CLAVM); of major named vessels; associated with other anomalies (Sturge–Weber, Klippel–Trenaunay, Parkes Weber, Proteus, CLOVES, Maffucci, PROS)"]),
 ("Differentiate infantile haemangioma from vascular malformation.", ["Haemangioma: usually absent or a premonitory mark at birth; appears in first weeks; rapid proliferation till 3–5 months (80% of final size), slow involution over years; GLUT-1 positive; female, premature, low birth weight, multiple gestation, placental anomalies", "Malformation: present at birth (may be inapparent), grows proportionately with the child, never involutes, may enlarge with trauma, infection, hormones; GLUT-1 negative; flow characteristics on Doppler (slow vs fast flow)"]),
 ("Describe clinical types of infantile haemangioma.", ["Superficial (bright red, lobulated 'strawberry'), deep (bluish subcutaneous swelling), mixed", "Pattern: focal, segmental (plaque in a developmental segment — more complications), indeterminate, multifocal (≥5 lesions — screen for hepatic haemangiomas with ultrasound)", "Abortive/minimal-growth haemangioma (telangiectatic patch, lower body)"]),
 ("Which haemangiomas are high-risk and need treatment?", ["Life-threatening: airway ('beard area' segmental — subglottic), liver (high-output cardiac failure, hypothyroidism), large lesions with cardiac failure", "Functional impairment: periocular (amblyopia, astigmatism), lip, nasal tip, ear canal, feeding problems", "Ulceration (commonest complication — lip, anogenital, flexures; painful, scarring)", "Disfigurement: central face, large facial, nose ('Cyrano'), breast in girls", "Associated syndromes: PHACE (Posterior fossa anomalies, Haemangioma (large segmental facial), Arterial anomalies, Cardiac defects/coarctation, Eye anomalies, ± sternal cleft/supraumbilical raphe); LUMBAR/SACRAL/PELVIS (lumbosacral haemangioma with spinal dysraphism, genitourinary, anorectal anomalies — do spine USG/MRI)"]),
 ("Treatment of infantile haemangioma.", ["Oral propranolol — first line for high-risk lesions: 1 mg/kg/day increasing to 2–3 mg/kg/day in 2–3 divided doses with feeds, start ideally by 1–2 months of age (before 5 months), continue till ~12 months of age (6 months minimum); baseline examination (heart rate, BP, ± ECG if bradycardia/heart disease), side effects — hypoglycaemia (feed regularly; stop if not feeding), bronchospasm, bradycardia, hypotension, sleep disturbance, cold extremities; rebound growth on stopping", "Atenolol (fewer CNS effects) and nadolol as alternatives", "Topical timolol 0.5% gel for small superficial lesions", "Systemic/intralesional steroids (second line), vincristine, sirolimus (kaposiform)", "Pulsed-dye laser for ulceration and residual telangiectasia; surgery for fibrofatty residue after involution", "Ulcer care: barrier creams, dressings, topical antibiotics, propranolol"]),
 ("Mechanism of propranolol in haemangiomas.", ["Vasoconstriction (early colour change), inhibition of VEGF and bFGF (angiogenesis), induction of apoptosis of endothelial cells, effects on haemangioma stem cells and renin–angiotensin system"]),
 ("What is Kasabach–Merritt phenomenon?", ["Profound thrombocytopenia and consumptive coagulopathy due to platelet trapping in kaposiform haemangioendothelioma or tufted angioma (NOT infantile haemangioma)", "Rapidly enlarging, firm, purpuric/ecchymotic mass in infancy; treat with sirolimus, vincristine, steroids; avoid platelet transfusion unless bleeding"]),
 ("Describe port-wine stain and Sturge–Weber syndrome.", ["Port-wine stain (capillary malformation): pink-red macular patch present at birth, persists, darkens and thickens with age (nodularity — 'cobblestoning'), soft-tissue hypertrophy; somatic GNAQ mutation", "Sturge–Weber: facial CM in V1 (forehead/upper eyelid) distribution + ipsilateral leptomeningeal angiomatosis (seizures, hemiparesis, intellectual disability, tram-track calcification on imaging) + eye (glaucoma, choroidal haemangioma)", "Treatment of PWS: pulsed-dye laser (585/595 nm) early in infancy — best results; topical rapamycin adjunct; MRI brain and eye check for V1 lesions"]),
 ("What is Klippel–Trenaunay syndrome? (PYQ)", ["Capillary–lymphatic–venous malformation of a limb (usually lower) + soft-tissue and bone overgrowth (limb hypertrophy) + varicosities/persistent embryonic lateral marginal vein (vein of Servelle) — slow flow; PIK3CA mutation (PROS spectrum)", "Complications: DVT/pulmonary embolism, bleeding, lymphatic leaks, cellulitis, limb-length discrepancy, coagulopathy", "Parkes Weber syndrome — similar but with arteriovenous fistulas (fast flow; RASA1) — high-output cardiac failure", "Management: compression, sclerotherapy, sirolimus, alpelisib (PIK3CA inhibitor), orthopaedic correction, anticoagulation when indicated"]),
 ("Write a short note on blue rubber bleb naevus syndrome (PYQ).", ["Multifocal venous malformations of skin (soft, compressible blue rubbery nodules that refill after pressure, may be painful/sweat) and GI tract (bleeding → iron-deficiency anaemia); TEK (TIE2) somatic mutations", "Treatment: iron, endoscopic ablation/resection of bleeding lesions, sirolimus"]),
 ("Enumerate syndromes associated with vascular anomalies (PYQ).", ["Sturge–Weber, Klippel–Trenaunay, Parkes Weber, Proteus, CLOVES, PHACE, LUMBAR, Maffucci (enchondromas + spindle-cell haemangiomas; risk of chondrosarcoma), blue rubber bleb, Cobb (spinal AVM + cutaneous vascular lesion in dermatome), von Hippel–Lindau, hereditary haemorrhagic telangiectasia (Osler–Weber–Rendu — epistaxis, mucocutaneous telangiectasia, AVMs; ENG/ACVRL1), ataxia-telangiectasia, capillary malformation–AVM (RASA1), macrocephaly–capillary malformation (M-CM), Beckwith–Wiedemann (glabellar naevus flammeus)"]),
 ("Lasers for vascular lesions (PYQ).", ["Selective photothermolysis targeting oxyhaemoglobin (peaks 418, 542, 577 nm): pulsed-dye laser 585/595 nm (port-wine stain, haemangioma, telangiectasia, rosacea), KTP 532 nm, long-pulsed Nd:YAG 1064 nm (deeper veins, leg veins), IPL, alexandrite 755 nm (hypertrophic PWS)", "Side effects: purpura, dyspigmentation, blistering, scarring"]),
 ],
 spot=["Absent at birth, grows fast, then involutes, GLUT-1+ — infantile haemangioma", "Propranolol 2–3 mg/kg/day", "V1 port-wine stain — look for Sturge–Weber; KMP is with kaposiform HE, not infantile haemangioma"]),

dict(case="Henoch–Schönlein purpura (IgA vasculitis)", src=f"{PYQ}; {IA} (Cutaneous vasculitis); 2012 Chapel Hill nomenclature; EULAR/PRINTO/PRES 2010 criteria",
 qa=[
 ("Define IgA vasculitis (HSP).", ["Small-vessel vasculitis with IgA1-dominant immune deposits affecting skin, joints, gut and kidneys; commonest systemic vasculitis of childhood (3–15 y, peak 4–6), often after upper respiratory infection (group A streptococcus); adults have more renal disease"]),
 ("Classify vasculitis (PYQ) — Chapel Hill 2012.", ["Large vessel: Takayasu arteritis, giant cell arteritis", "Medium vessel: polyarteritis nodosa, Kawasaki disease", "Small vessel — ANCA-associated: microscopic polyangiitis, granulomatosis with polyangiitis (Wegener's), eosinophilic GPA (Churg–Strauss); immune-complex: anti-GBM disease, cryoglobulinaemic vasculitis, IgA vasculitis (HSP), hypocomplementaemic urticarial vasculitis (anti-C1q)", "Variable vessel: Behçet's, Cogan's syndrome", "Single-organ: cutaneous leukocytoclastic angiitis, cutaneous arteritis, primary CNS vasculitis", "Vasculitis associated with systemic disease (lupus, RA, sarcoid) and with probable aetiology (hepatitis B PAN, hepatitis C cryoglobulinaemia, drug-associated, cancer-associated)"]),
 ("Give the EULAR/PRINTO/PRES classification criteria.", ["Mandatory: purpura or petechiae with lower-limb predominance (non-thrombocytopenic)", "Plus ≥1 of: diffuse abdominal pain; histopathology showing leukocytoclastic vasculitis or proliferative glomerulonephritis with predominant IgA deposits; arthritis or arthralgia; renal involvement (proteinuria >0.3 g/24 h or haematuria/red cell casts)"]),
 ("Describe the clinical features.", ["Skin (100%): palpable purpura — symmetrical on buttocks, extensor lower limbs, ankles (dependent areas); starts as urticarial/erythematous papules; may become bullous, haemorrhagic, necrotic; oedema of scalp, face, hands, scrotum in young children", "Joints (75%): transient arthralgia/arthritis of knees and ankles, non-deforming", "GI (50–75%): colicky abdominal pain, vomiting, GI bleed (melaena), intussusception (ileo-ileal), bowel perforation", "Renal (20–50%): microscopic haematuria, proteinuria, nephritic/nephrotic syndrome — determines long-term prognosis (ESRD in 1–2% children, more in adults)", "Others: orchitis (mimics torsion), CNS vasculitis, pulmonary haemorrhage (rare)"]),
 ("Classify purpura (PYQ).", ["Non-palpable (haemorrhage without vessel inflammation): thrombocytopenic (ITP, TTP, marrow failure, DIC), platelet dysfunction, coagulation defects, vascular fragility (senile/actinic purpura, steroid purpura, scurvy — perifollicular haemorrhage with corkscrew hairs, Ehlers–Danlos, amyloidosis — pinch purpura), raised intravascular pressure (cough, vomiting), pigmented purpuric dermatoses", "Palpable (inflammatory — vasculitis): leukocytoclastic vasculitis, IgA vasculitis, cryoglobulinaemia, urticarial vasculitis", "Retiform/net-like (occlusion of vessels): APS, cryoglobulinaemia type I, calciphylaxis, purpura fulminans, warfarin/heparin necrosis, septic emboli, cholesterol emboli, levamisole-adulterated cocaine"]),
 ("Discuss the evaluation of vasculitis (PYQ).", ["Confirm vasculitis: skin biopsy from a fresh (<24–48 h) lesion for histology + DIF (IgA in vessel walls in HSP — best in lesions <48 h old)", "Assess extent: urine dipstick and microscopy (haematuria, casts), urine protein:creatinine ratio, serum creatinine, BP; stool occult blood, abdominal ultrasound (intussusception) if pain; chest X-ray; nerve conduction if neuropathy", "Find cause: CBC, ESR/CRP, ASO, throat swab, hepatitis B/C, HIV, ANA, anti-dsDNA, RF, C3/C4, cryoglobulins, ANCA (MPO, PR3), serum IgA (raised in 50%), serum protein electrophoresis, drug history, malignancy screen in adults"]),
 ("Histopathology.", ["Leukocytoclastic vasculitis of superficial dermal post-capillary venules: fibrinoid necrosis of vessel walls, neutrophils with nuclear dust (leukocytoclasia), extravasated RBCs, endothelial swelling", "DIF: granular IgA (± C3) deposits in vessel walls — key differentiating feature", "Kidney: mesangial proliferative glomerulonephritis with mesangial IgA (same as IgA nephropathy)"]),
 ("Differential diagnosis.", ["Other small-vessel vasculitis (hypersensitivity/drug, cryoglobulinaemia, urticarial vasculitis, ANCA), acute haemorrhagic oedema of infancy (large rosette/cockade purpura on face and limbs of well infant <2 y, self-limiting), ITP (non-palpable), meningococcaemia (sick child, retiform purpura — emergency), child abuse, Rocky Mountain spotted fever, septic emboli"]),
 ("Management.", ["Mostly self-limiting (4–6 weeks): rest, leg elevation, compression; NSAIDs/paracetamol for arthralgia (avoid NSAIDs if renal involvement)", "Severe abdominal pain, scrotal involvement, extensive necrotic skin: systemic corticosteroids (prednisolone 1–2 mg/kg/day) — relieve GI/joint symptoms; do not prevent nephritis", "Renal disease (proteinuria, nephrotic, crescentic GN): steroids (pulse methylprednisolone) + azathioprine/mycophenolate/cyclophosphamide; ACE inhibitors for proteinuria; nephrology follow-up", "Skin-only chronic: dapsone, colchicine", "Urine monitoring (dipstick and BP) weekly for the first month, then monthly up to 6–12 months — nephritis can appear late"]),
 ("Prognosis.", ["Excellent in most children; recurrences in ~1/3 within months; long-term outcome depends on renal involvement — worse in adults, nephrotic range proteinuria, crescents on biopsy"]),
 ],
 spot=["Palpable purpura on buttocks/legs + abdominal pain + arthritis + haematuria in a child — IgA vasculitis", "DIF: IgA in vessel walls", "Monitor urine for 6–12 months"]),

dict(case="Lipodermatosclerosis", src=f"{PYQ}; {IA} (Venous disease; panniculitis)",
 qa=[
 ("Define lipodermatosclerosis (LDS).", ["Chronic sclerosing lobular/septal panniculitis of the lower legs due to chronic venous insufficiency (sclerosing panniculitis, hypodermitis sclerodermiformis); a C4b sign in CEAP classification", "Middle-aged and older women, obesity, venous hypertension"]),
 ("Describe acute and chronic phases.", ["Acute: painful, warm, erythematous, indurated plaque on medial lower leg above the malleolus — often mistaken for cellulitis (bilateral, not febrile, no response to antibiotics)", "Chronic: woody, bound-down induration with hyperpigmentation (haemosiderin), sharply demarcated from normal skin above; circumferential fibrosis with oedema above produces an 'inverted champagne-bottle' or 'inverted bowling-pin' leg", "Associated: varicose veins, stasis eczema, atrophie blanche, venous ulcers (risk ↑)"]),
 ("Pathogenesis.", ["Venous hypertension → capillary leakage of fibrinogen → pericapillary fibrin cuffs, tissue hypoxia → fat necrosis and fibrosis; fibrinolytic dysfunction; TGF-β1-driven fibrosis"]),
 ("Histopathology.", ["Early: septal lymphocytic infiltrate, ischaemic fat necrosis in centre of lobules", "Late: septal fibrosis/sclerosis, lipomembranous (membranocystic) fat necrosis (feathery eosinophilic membranes lining cystic spaces), haemosiderin, stasis changes (lobular proliferation of thick-walled capillaries)", "Biopsy discouraged — poor healing and ulcer risk; diagnosis is clinical"]),
 ("Differential diagnosis.", ["Acute: cellulitis (unilateral, fever, raised markers), erythema nodosum, morphoea, DVT, panniculitis (lupus profundus, pancreatic)", "Chronic: morphoea profunda, necrobiosis lipoidica, pretibial myxoedema (Graves'), scleroderma, eosinophilic fasciitis, elephantiasis nostras"]),
 ("Investigations.", ["Venous duplex ultrasound for reflux/obstruction, ABPI before compression, Doppler to exclude DVT; blood counts/CRP to exclude infection"]),
 ("Management.", ["Compression therapy (graduated stockings 30–40 mmHg; bandages initially) — mainstay; leg elevation, exercise, weight loss", "Treat venous reflux: endovenous ablation, sclerotherapy, surgery", "Drugs: pentoxifylline, stanozolol/danazol (anabolic steroids — fibrinolytic; side effects limit use), oxandrolone, aspirin; intralesional triamcinolone for acute painful areas; NSAIDs/analgesia", "Avoid trauma and biopsy; treat stasis eczema"]),
 ("Prognosis.", ["Chronic progressive condition; acute pain improves with compression; increased risk of venous ulceration"]),
 ],
 spot=["Inverted champagne-bottle leg with woody induration — lipodermatosclerosis", "Bilateral 'cellulitis' not responding to antibiotics — think acute LDS", "Avoid biopsy"]),

dict(case="Pigmented purpuric dermatosis", src=f"{PYQ}; {IA} (Pigmented purpuric dermatoses)",
 qa=[
 ("What are pigmented purpuric dermatoses (PPD)?", ["Group of chronic benign capillaritides — lymphocytic inflammation of superficial dermal capillaries with RBC extravasation and haemosiderin deposition, giving petechiae ('cayenne pepper' spots) on a brown background; mainly lower legs; not associated with systemic disease or platelet defects"]),
 ("Name the clinical variants.", ["Schamberg's disease (progressive pigmentary purpura — commonest): irregular orange-brown patches with cayenne-pepper petechiae on shins/ankles of men", "Purpura annularis telangiectodes of Majocchi: annular patches with telangiectatic punctae, young women, legs", "Pigmented purpuric lichenoid dermatosis of Gougerot and Blum: lichenoid rust-brown papules coalescing into plaques, middle-aged men", "Lichen aureus: solitary golden-brown patch, often unilateral on leg/trunk, persistent, children/young adults", "Eczematid-like purpura of Doucas and Kapetanakis: itchy, scaly, eczematous, widespread", "Others: itching purpura of Lowenthal, granulomatous PPD (Asians), linear, transitory"]),
 ("Aetiology / associations.", ["Mostly idiopathic; exacerbated by venous hypertension, exercise, standing, gravitational dependency", "Drugs: aspirin, NSAIDs, paracetamol, carbamazepine, furosemide, thiamine, glipizide, chlordiazepoxide, sildenafil, medroxyprogesterone; contact allergens (textile dyes, rubber, khaki clothing)", "Associations: diabetes, hyperlipidaemia (granulomatous variant), hepatitis C, rheumatoid arthritis; some persistent PPD can evolve into/mimic mycosis fungoides (clonal T cells)"]),
 ("Histopathology.", ["Superficial perivascular lymphocytic infiltrate around papillary dermal capillaries with endothelial swelling, extravasated RBCs and haemosiderin-laden macrophages (Perls' stain), no fibrinoid necrosis (not true vasculitis); lichenoid infiltrate in Gougerot–Blum and lichen aureus; spongiosis in eczematid type"]),
 ("Differential diagnosis.", ["Stasis dermatitis/haemosiderosis (venous disease), drug-induced purpura, leukocytoclastic vasculitis (palpable), thrombocytopenic purpura, scurvy (perifollicular), MF (purpuric MF — biopsy, clonality), Kaposi sarcoma, post-inflammatory hyperpigmentation, cholesterol/hyperglobulinaemic purpura (Waldenström)"]),
 ("Investigations.", ["Dermoscopy: red globules/dots over copper-orange background with brown network", "CBC with platelets, coagulation profile, blood sugar, lipids, LFT, HCV; review drugs; biopsy in atypical/persistent cases; TCR clonality if MF suspected"]),
 ("Treatment.", ["Reassurance; stop suspect drugs; treat venous insufficiency (compression stockings, elevation)", "Topical steroids (moderate–potent) or tacrolimus for itch/inflammation", "Oral vitamin C 500 mg BD + rutoside (flavonoid) 50 mg BD — improves capillary fragility; pentoxifylline, griseofulvin, colchicine (case reports)", "NB-UVB/PUVA — particularly for widespread or MF-like disease", "Lasers (PDL) for cosmetically disturbing lesions"]),
 ("Prognosis.", ["Chronic, relapsing–remitting over years; benign; pigmentation may persist; follow persistent widespread lesions for MF"]),
 ],
 spot=["Cayenne-pepper petechiae on orange-brown patches of shins — Schamberg's PPD", "Golden-brown solitary patch — lichen aureus", "Vitamin C + rutoside"]),

dict(case="Pyogenic granuloma (lobular capillary haemangioma)", src=f"{PYQ}; {IA} (Vascular tumours)",
 qa=[
 ("What is pyogenic granuloma (PG)?", ["Common acquired benign vascular tumour (lobular capillary haemangioma) of skin and mucosa; neither infective ('pyogenic') nor granulomatous — misnomer; children and young adults, pregnant women (granuloma gravidarum/epulis on gingiva)"]),
 ("Triggers / associations.", ["Minor trauma (often), pregnancy and OCPs (hormonal), burns, ingrown toenails", "Drugs: systemic retinoids (isotretinoin, acitretin — periungual), EGFR inhibitors (cetuximab, gefitinib — periungual), BRAF/MEK inhibitors, capecitabine, antiretrovirals (indinavir), cyclosporine, taxanes", "Multiple/satellite PG after removal; within port-wine stains"]),
 ("Describe the lesion.", ["Rapidly growing (weeks) solitary bright red, friable, sessile or pedunculated papule/nodule (5–10 mm), with glistening or eroded surface and a collarette of scale at its base", "Bleeds profusely with minor trauma; sites — fingers, lips, face, gingiva, scalp, nail folds"]),
 ("Histopathology.", ["Exophytic polypoid lesion with lobules of proliferating capillaries separated by fibrous septa, a central feeding vessel, surface ulceration with inflammation, epidermal collarette at the base (inward-growing rete ridges)", "GLUT-1 negative (vs infantile haemangioma)"]),
 ("Differential diagnosis.", ["Amelanotic melanoma (most important — any atypical/recurrent PG should be biopsied and sent for histology), SCC/keratoacanthoma, Kaposi sarcoma, bacillary angiomatosis (HIV — Bartonella), glomus tumour, cherry angioma, infantile haemangioma, Spitz naevus, metastasis, granulation tissue (ingrown nail), angiosarcoma, eccrine poroma"]),
 ("Treatment.", ["Shave excision with curettage and cautery of the base (electrodesiccation) — lowest recurrence when the feeding vessel is cauterised; send tissue for histopathology", "Surgical excision with closure (recurrence lowest), cryotherapy, laser (pulsed-dye, CO2, Nd:YAG), silver nitrate cautery for small lesions", "Topical timolol 0.5% (children, periungual), imiquimod, sodium tetradecyl sulphate sclerotherapy", "Pregnancy-related: may regress after delivery; drug-induced: dose reduction, topical timolol"]),
 ("Write short notes on glomus tumour (PYQ).", ["Benign tumour of the glomus body (modified smooth muscle cells regulating thermoregulatory arteriovenous shunts — Sucquet–Hoyer canal)", "Solitary: subungual blue-red spot with severe paroxysmal pain, cold sensitivity and point tenderness — Love's pin test, Hildreth's test (pain abolished by tourniquet), cold sensitivity test; X-ray may show bony erosion; MRI", "Multiple glomuvenous malformations (glomangiomas) — autosomal dominant (glomulin), less painful, children", "Treatment: surgical excision"]),
 ],
 spot=["Rapidly growing bleeding red papule with collarette — pyogenic granuloma", "Always send for histology — exclude amelanotic melanoma", "Subungual painful blue spot + cold sensitivity — glomus tumour"]),
]
